/* ---------- time zones & availability ---------- */
const USER_TZ=(()=>{try{return Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC'}catch(e){return 'UTC'}})();
const tzParts=(tz,d)=>{const p={};new Intl.DateTimeFormat('en-US',{timeZone:tz,hourCycle:'h23',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',weekday:'short'}).formatToParts(d).forEach(x=>p[x.type]=x.value);return p};
const tzOff=(tz,d)=>{const p=tzParts(tz,d);return (Date.UTC(+p.year,+p.month-1,+p.day,+p.hour%24,+p.minute,+p.second)-d.getTime())/6e4};
const toUTC=(ds,tm,tz)=>{const [y,m,d]=ds.split('-').map(Number),[h,mi]=tm.split(':').map(Number);const g=Date.UTC(y,m-1,d,h,mi);return new Date(g-tzOff(tz,new Date(g))*6e4)};
const officeToday=tz=>{const p=tzParts(tz,new Date());return {ds:`${p.year}-${p.month}-${p.day}`,hm:`${p.hour%24}`.padStart(2,'0')+':'+p.minute}};
const TIMES=['09:00','09:30','10:00','10:30','11:00','11:30','13:00','13:30','14:00','14:30','15:00','15:30','16:00','16:30'];
const isWeekend=ds=>{const d=new Date(ds+'T12:00:00Z').getUTCDay();return d===0||d===6};
function slots(aid,ds){const a=adv(aid);if(!a||isWeekend(ds))return [];const tz=off(a.off).tz,now=officeToday(tz);if(ds<now.ds)return [];
 return TIMES.map(t=>({t,free:(hash(aid+ds+t)%100)>40&&!(ds===now.ds&&t<=now.hm)&&!S.bookings.some(b=>b.adv===aid&&b.date===ds&&b.time===t&&b.id!==S.bk.resched)}))}
const addDays=(ds,n)=>{const d=new Date(ds+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)};
function nextSlot(aid){const tz=off(adv(aid).off).tz;let ds=officeToday(tz).ds;for(let i=0;i<30;i++){const f=slots(aid,ds).find(x=>x.free);if(f)return {ds,t:f.t};ds=addDays(ds,1)}return null}
const fmtDate=(ds,o={weekday:'short',month:'short',day:'numeric'})=>new Date(ds+'T12:00:00Z').toLocaleDateString('en-US',{...o,timeZone:'UTC'});
const fmtTime=t=>{const [h,m]=t.split(':').map(Number);return `${(h%12)||12}:${String(m).padStart(2,'0')} ${h<12?'AM':'PM'}`};
const localTime=(ds,t,tz)=>toUTC(ds,t,tz).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit',timeZone:USER_TZ});
const localDate=(ds,t,tz)=>toUTC(ds,t,tz).toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric',timeZone:USER_TZ});

