function bindCur(root){$$('[data-cur]',root).forEach(s=>s.onchange=()=>{S.cur=s.value;ls('cur',S.cur);$$('[data-cur]').forEach(x=>x.value=S.cur);document.dispatchEvent(new Event('cur'))})}
function toast(msg){const t=document.createElement('div');t.className='toast';t.innerHTML=ic('check')+esc(msg);$('#toasts').appendChild(t);setTimeout(()=>{t.style.transition='opacity .3s';t.style.opacity=0;setTimeout(()=>t.remove(),300)},3200)}
