 // testimonials
 const card=$('#tmCard');let paused=false;const go=i=>{S.tmI=(i+TM.length)%TM.length;$$('.tm-it').forEach((e,k)=>{e.classList.toggle('on',k===S.tmI);e.setAttribute('aria-hidden',k!==S.tmI)});$$('#tmD button').forEach((b,k)=>{b.setAttribute('aria-current',k===S.tmI);if(k===S.tmI){b.style.display='none';b.offsetWidth;b.style.display=''}})};
 $$('#tmD button').forEach((b,k)=>b.onclick=()=>{go(k);tmT=restart()});$('#tmP').onclick=()=>{go(S.tmI-1);tmT=restart()};$('#tmN').onclick=()=>{go(S.tmI+1);tmT=restart()};
 let tmT=null;const restart=()=>{clearInterval(tmT);return timer(()=>{if(!paused&&!document.hidden)go(S.tmI+1)},6000)};tmT=restart();
 card.onmouseenter=()=>{paused=true;card.classList.add('paused')};card.onmouseleave=()=>{paused=false;card.classList.remove('paused')};
 let sx=null;card.addEventListener('pointerdown',e=>sx=e.clientX);card.addEventListener('pointerup',e=>{if(sx!=null&&Math.abs(e.clientX-sx)>50){go(S.tmI+(e.clientX<sx?1:-1));tmT=restart()}sx=null});
