 <section class="wrap"><div class="svg-grid">${SV.map((s,i)=>`<a class="sg" href="#service-${s.s}" style="--d:${i*.06}s">${ph(s.img,s.t,s.pos)}<div class="bd"><span class="tag" style="justify-self:start">${ic(s.ic,'width:14px;height:14px')}${CATN[s.cat]}</span><h3>${s.t}</h3><p>${s.sh}</p><span style="display:flex;justify-content:space-between;align-items:center;margin-top:6px;font-weight:700">From ${money(s.from)}<span class="circ" style="width:38px;height:38px">${ic('ne','width:15px;height:15px')}</span></span></div></a>`).join('')}</div></section>
