/* ---------- motion engine ---------- */
let io;
function initReveal(){io?.disconnect();io=new IntersectionObserver(es=>es.forEach(e=>{if(!e.isIntersecting)return;const t=e.target;t.classList.add('in');io.unobserve(t);$$('[data-count]',t).forEach(countUp);if(t.dataset.count)countUp(t)}),{threshold:.15,rootMargin:'0px 0px -6% 0px'});
 $$('.rv,.st,[data-count]').forEach(el=>{if(RM){el.classList.add('in');countUp(el,true);return}io.observe(el)})}
function countUp(el,now){if(!el.dataset.count||el.dataset.done)return;el.dataset.done=1;const to=+el.dataset.count,dec=+(el.dataset.dec||0),pre=el.dataset.pre||'',suf=el.dataset.suf||'';const fmt=v=>pre+(dec?v.toFixed(dec):Math.round(v).toLocaleString('en-US'))+suf;if(now||RM){el.textContent=fmt(to);return}
 const t0=performance.now(),D=1600;const f=t=>{const p=Math.min(1,(t-t0)/D),e=1-Math.pow(1-p,4);el.textContent=fmt(to*e);if(p<1)requestAnimationFrame(f)};requestAnimationFrame(f)}
let ticking=false,lastY=scrollY,vel=0;
function measure(){const hs=$('#hs'),tr=$('#hsT');if(hs&&tr){if(innerWidth<=900){hs.style.height='';S.hsDist=0;return}S.hsDist=Math.max(0,tr.scrollWidth-innerWidth);hs.style.height=(innerHeight+S.hsDist)+'px'}}
