 const cards=$$('#stack .sc');cards.forEach((c,i)=>{const nx=cards[i+1];if(!nx){c.style.transform='';c.style.filter='';return}const top=parseFloat(getComputedStyle(nx).top)||0;const d=nx.getBoundingClientRect().top-top;const p=clamp(1-d/(vh*.8),0,1);c.style.transform=`scale(${(1-p*.06).toFixed(4)})`;c.style.filter=`brightness(${(1-p*.12).toFixed(3)})`});
 const fl=$('#fill');if(fl){const r=fl.getBoundingClientRect(),p=clamp((vh*.85-r.top)/(r.height+vh*.35),0,1);const w=fl._w||(fl._w=$$('.wd',fl));const n=Math.round(p*w.length);w.forEach((s,i)=>s.classList.toggle('on',i<n))}
